DROP TABLE IF EXISTS `absensi`;
CREATE TABLE `absensi` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `pertemuan_id` int(11) NOT NULL,
  `anggota_id` int(11) DEFAULT NULL,
  `pengurus_id` int(11) DEFAULT NULL,
  `barcode_id` int(11) NOT NULL,
  `status` enum('hadir') NOT NULL DEFAULT 'hadir',
  `scan_time` datetime NOT NULL,
  `waktu_scan` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_absensi_anggota` (`pertemuan_id`,`anggota_id`),
  UNIQUE KEY `uq_absensi_pengurus` (`pertemuan_id`,`pengurus_id`),
  KEY `fk_absensi_anggota` (`anggota_id`),
  KEY `fk_absensi_pengurus` (`pengurus_id`),
  KEY `fk_absensi_barcode` (`barcode_id`),
  CONSTRAINT `fk_absensi_anggota` FOREIGN KEY (`anggota_id`) REFERENCES `anggota` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_absensi_barcode` FOREIGN KEY (`barcode_id`) REFERENCES `barcode` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_absensi_pengurus` FOREIGN KEY (`pengurus_id`) REFERENCES `pengurus_migrated_backup` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_absensi_pertemuan` FOREIGN KEY (`pertemuan_id`) REFERENCES `pertemuan` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=895 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `admin`;
CREATE TABLE `admin` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `username` varchar(50) NOT NULL,
  `password` varchar(255) NOT NULL,
  `full_name` varchar(120) NOT NULL,
  `last_login` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `anggota`;
CREATE TABLE `anggota` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `kode_qr` varchar(90) DEFAULT NULL,
  `nama` varchar(120) DEFAULT NULL,
  `nama_lengkap` varchar(120) NOT NULL,
  `kelas` varchar(80) NOT NULL,
  `jurusan` varchar(80) NOT NULL DEFAULT '-',
  `nis` varchar(30) DEFAULT NULL,
  `jenis_kelamin` enum('L','P') DEFAULT NULL,
  `jabatan` enum('Anggota','Pengurus') NOT NULL DEFAULT 'Anggota',
  `status` enum('Aktif','Nonaktif') NOT NULL DEFAULT 'Aktif',
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  `lp` enum('L','P') DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `nis` (`nis`)
) ENGINE=InnoDB AUTO_INCREMENT=177 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `barcode`;
CREATE TABLE `barcode` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `kode_unik` varchar(90) NOT NULL,
  `qr_value` varchar(255) NOT NULL,
  `anggota_id` int(11) DEFAULT NULL,
  `pengurus_id` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `kode_unik` (`kode_unik`),
  UNIQUE KEY `qr_value` (`qr_value`),
  UNIQUE KEY `anggota_id` (`anggota_id`),
  UNIQUE KEY `pengurus_id` (`pengurus_id`),
  CONSTRAINT `fk_barcode_anggota` FOREIGN KEY (`anggota_id`) REFERENCES `anggota` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_barcode_pengurus` FOREIGN KEY (`pengurus_id`) REFERENCES `pengurus_migrated_backup` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=184 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `geofence_settings`;
CREATE TABLE `geofence_settings` (
  `id` tinyint(3) unsigned NOT NULL,
  `lat` double DEFAULT NULL,
  `lng` double DEFAULT NULL,
  `radius` int(11) NOT NULL DEFAULT 600,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `pengurus_migrated_backup`;
CREATE TABLE `pengurus_migrated_backup` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nama_lengkap` varchar(120) NOT NULL,
  `kelas` varchar(80) NOT NULL,
  `tingkat_kelas` enum('X','XI') NOT NULL,
  `nis` varchar(30) NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `nis` (`nis`)
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `pertemuan`;
CREATE TABLE `pertemuan` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nama_pertemuan` varchar(120) NOT NULL,
  `pertemuan_ke` int(11) NOT NULL,
  `tanggal` date NOT NULL,
  `jam_mulai_scan` time NOT NULL,
  `jam_akhir_scan` time NOT NULL,
  `keterangan` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `manual_active` tinyint(1) NOT NULL DEFAULT 0,
  `is_libur` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=58 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


SET FOREIGN_KEY_CHECKS=1;
